        <div class="row g-3"><div class="col-12 col-xl-5"><div class="card"><div class="card-body"><h2 class="card-title"><?= $communiqueEdit ? 'Modifier le communiqué' : 'Nouveau communiqué' ?></h2>
            <form method="post" class="row g-3"><input type="hidden" name="csrf_token" value="<?= htmlspecialchars(csrf_token(), ENT_QUOTES, 'UTF-8') ?>"><input type="hidden" name="id" value="<?= (int) ($communiqueEdit['id'] ?? 0) ?>">
                <div class="col-12"><label class="form-label" for="communique-title">Titre</label><input class="form-control" id="communique-title" name="titre" required maxlength="255" value="<?= htmlspecialchars((string) ($communiqueEdit['titre'] ?? ''), ENT_QUOTES, 'UTF-8') ?>"></div>
