            </form>
        </div></div></div><div class="col-12 col-xl-7"><div class="card"><div class="card-body"><h2 class="card-title">Derniers communiqués</h2><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Titre</th><th>Promotion</th><th>Date</th><th>Actions</th></tr></thead><tbody><?php foreach ($communiqueRows as $row): ?><tr><td><?= htmlspecialchars($row['titre'] ?? '', ENT_QUOTES, 'UTF-8') ?></td><td><?= htmlspecialchars($row['promotion_titre'] ?? 'Non attribuée', ENT_QUOTES, 'UTF-8') ?></td><td><?= htmlspecialchars((string) $row['datepub'], ENT_QUOTES, 'UTF-8') ?></td><td><div class="d-flex flex-wrap gap-1"><a class="btn btn-sm btn-outline-secondary" href="?pages=communiques&amp;id=<?= (int) $row['id'] ?>"><i class="bi bi-pencil-square me-1" aria-hidden="true"></i> Modifier</a><form method="post"><input type="hidden" name="csrf_token" value="<?= htmlspecialchars(csrf_token(), ENT_QUOTES, 'UTF-8') ?>"><input type="hidden" name="record_id" value="<?= (int) $row['id'] ?>"><button class="btn btn-sm btn-outline-danger" type="submit" name="admin_action" value="delete"><i class="bi bi-trash me-1" aria-hidden="true"></i> Supprimer</button></form></div></td></tr><?php endforeach; ?></tbody></table></div><?php if (!$communiqueRows): ?><p class="admin-empty-state">Aucun communiqué enregistré.</p><?php endif; ?></div></div></div></div>
